bool IsDate1BeforeDate2(sDate Date1, sDate Date2)
{
    return (Date1.Year < Date2.Year) ? true : ((Date1.Year ==
    Date2.Year) ? (Date1.Month < Date2.Month ? true : (Date1.Month ==
    Date2.Month ? Date1.Day < Date2.Day : false)) : false);
}

void SwapDates(sDate& Date1,sDate& Date2)
{
    sDate TempDate;

    TempDate.Year = Date1.Year;
    TempDate.Month = Date1.Month;
    TempDate.Day = Date1.Day;

    Date1.Year = Date2.Year;
    Date1.Month = Date2.Month;
    Date1.Day = Date2.Day;

    Date2.Year = TempDate.Year;
    Date2.Month = TempDate.Month;
    Date2.Day = TempDate.Day;
}

int GetDifferenceInDays(sDate Date1, sDate Date2, bool
IncludeEndDay = false)
{
    int Days = 0;
    short SwapFlagValue = 1;

   if (!IsDate1BeforeDate2(Date1, Date2))
   {
       SwapDates(Date1, Date2);
       SwapFlagValue = -1;
   }

    while (IsDate1BeforeDate2(Date1, Date2))
    {
        Days++;
        Date1 = IncreaseDayByOneDay(Date1);
    }
    return IncludeEndDay ? ++Days * SwapFlagValue : Days * SwapFlagValue;
}

sDate GetsystemDate()
{
    sDate Date{};

    time_t t = time(0);
    tm* now = localtime(&t);

    Date.Day = now->tm_mday;
    Date.Month = now->tm_mon + 1;
    Date.Year = now->tm_year + 1900;

    return Date;
}

void PrintDifferences(sDate Date1, sDate Date2)
{
    cout << "\nDifference in days is: " << GetDifferenceInDays(Date1, Date2);
    cout << "\nDiffenece including end day:" << GetDifferenceInDays(Date1, Date2, true);
}

int main() {
    sDate Date1 = ReadFullDate();
    sDate Date2 = ReadFullDate();
    PrintDifferences(Date1, Date2);

    system("pause>0");
    return 0;
}
