    // Transactions
    void ShowDepositScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tDeposit Screen";
        cout << "\n-----------------------------------\n";
        string AccountNumber = "";
        cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        sClient Client;
        while (!FindClientByAccountNumber(AccountNumber, vClients, Client)) {
            cout << "\nClient with Account Number [" << AccountNumber << "] does not exist.\n";
            cout << "Please enter AccountNumber? "; cin >> AccountNumber;
        }
        double Amount = 0;
        cout << "\nPlease enter deposit amount? "; cin >> Amount;
        char Answer = 'n';
        cout << "\nAre you sure you want to perform this transaction? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            for (sClient& C : vClients) {
                if (C.AccountNumber == AccountNumber) {
                    C.AccountBalance += Amount;
                    SaveClientsDataToFile(ClientsFileName, vClients);
                    cout << "\n\nDone Successfully. New balance is: " << C.AccountBalance;
                    break;
                }
            }
        }
    }

    void ShowWithDrawScreen() {
        cout << "\n-----------------------------------\n";
        cout << "\tWithdraw Screen";
        cout << "\n-----------------------------------\n";
        string AccountNumber = "";
        cout << "\nPlease enter AccountNumber? "; cin >> AccountNumber;
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        sClient Client;
        while (!FindClientByAccountNumber(AccountNumber, vClients, Client)) {
            cout << "\nClient with Account Number [" << AccountNumber << "] does not exist.\n";
            cout << "Please enter AccountNumber? "; cin >> AccountNumber;
        }
        double Amount = 0;
        cout << "\nPlease enter withdraw amount? "; cin >> Amount;
        while (Amount > Client.AccountBalance) {
            cout << "\nAmount Exceeds the balance, you can withdraw up to : " << Client.AccountBalance << endl;
            cout << "Please enter withdraw amount? "; cin >> Amount;
        }
        char Answer = 'n';
        cout << "\nAre you sure you want to perform this transaction? y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            for (sClient& C : vClients) {
                if (C.AccountNumber == AccountNumber) {
                    C.AccountBalance -= Amount;
                    SaveClientsDataToFile(ClientsFileName, vClients);
                    cout << "\n\nDone Successfully. New balance is: " << C.AccountBalance;
                    break;
                }
            }
        }
    }

    void ShowTotalBalances() {
        vector<sClient> vClients = LoadClientsDataFromFile(ClientsFileName);
        cout << "\n\t\t\t\t\tBalances List (" << vClients.size() << ") Client(s).";
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        cout << "| " << left << setw(15) << "Accout Number";
        cout << "| " << left << setw(40) << "Client Name";
        cout << "| " << left << setw(12) << "Balance";
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        double TotalBalances = 0;
        if (vClients.size() == 0)
            cout << "\t\t\t\tNo Clients Available In the System!";
        else {
            for (sClient Client : vClients) {
                cout << "| " << setw(15) << left << Client.AccountNumber;
                cout << "| " << setw(40) << left << Client.Name;
                cout << "| " << setw(12) << left << Client.AccountBalance;
                cout << endl;
                TotalBalances += Client.AccountBalance;
            }
        }
        cout << "\n_______________________________________________________";
        cout << "_________________________________________\n" << endl;
        cout << "\t\t\t\t\t   Total Balances = " << TotalBalances << endl;
    }

