void clsBankController::_ShowManageUsersMenu() {
    bool BackToMain = false;
    while (!BackToMain) {
        Util::ClearScreen();
        cout << "===========================================\n";
        cout << "\t\tManage Users Menu Screen\n";
        cout << "===========================================\n";
        cout << "\t[1] List Users.\n";
        cout << "\t[2] Add New User.\n";
        cout << "\t[3] Delete User.\n";
        cout << "\t[4] Update User.\n";
        cout << "\t[5] Find User.\n";
        cout << "\t[6] Main Menu.\n";
        cout << "===========================================\n";

        short Choice;
        cout << "Choose what do you want to do? [1 to 6]? "; cin >> Choice;
        enManageUsersMenuOptions Option = static_cast<enManageUsersMenuOptions>(Choice);
        if (Option == enManageUsersMenuOptions::eManageMainMenu) {
            BackToMain = true;
            break;
        }
        _PerformManageUsersMenuOption(Option);
    }
}

void clsBankController::_PerformManageUsersMenuOption(enManageUsersMenuOptions Option) {
    switch (Option) {
        case enManageUsersMenuOptions::eListUsers:
            Util::ClearScreen();
            _ShowAllUsersScreen();
            cout << "\n\nPress any key to go back to Manage Users Menu...";
            Util::Pause();
            break;
        case enManageUsersMenuOptions::eAddNewUser:
            Util::ClearScreen();
            _ShowAddNewUserScreen();
            cout << "\n\nPress any key to go back to Manage Users Menu...";
            Util::Pause();
            break;
        case enManageUsersMenuOptions::eDeleteUser:
            Util::ClearScreen();
            _ShowDeleteUserScreen();
            cout << "\n\nPress any key to go back to Manage Users Menu...";
            Util::Pause();
            break;
        case enManageUsersMenuOptions::eUpdateUser:
            Util::ClearScreen();
            _ShowUpdateUserScreen();
            cout << "\n\nPress any key to go back to Manage Users Menu...";
            Util::Pause();
            break;
        case enManageUsersMenuOptions::eFindUser:
            Util::ClearScreen();
            _ShowFindUserScreen();
            cout << "\n\nPress any key to go back to Manage Users Menu...";
            Util::Pause();
            break;
        case enManageUsersMenuOptions::eManageMainMenu:
            break;
    }
}

void clsBankController::_ShowAllUsersScreen() {
    vector<clsUser> vUsers = clsUser::GetUsersList();
    cout << "\n\t\t\t\t\tUsers List (" << vUsers.size() << ") User(s).";
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
    cout << "| " << left << setw(15) << "User Name";
    cout << "| " << left << setw(10) << "Password";
    cout << "| " << left << setw(12) << "Permissions";
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;

    if (vUsers.empty()) {
        cout << "\t\t\t\tNo Users Available In the System!";
    } else {
        for (clsUser& U : vUsers) {
            cout << "| " << setw(15) << left << U.GetUserName();
            cout << "| " << setw(10) << left << U.GetPassword();
            cout << "| " << setw(12) << left << U.GetPermissions() << endl;
        }
    }
    cout << "\n_______________________________________________________";
    cout << "_________________________________________\n" << endl;
}

int ReadPermissions() {
    int Permissions = 0;
    char Answer;
    cout << "\nDo you want to give full access? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') return -1;

    cout << "\nDo you want to give access to: \n ";
    cout << "\nShow Client List? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pListClients;
    cout << "\nAdd New Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pAddNewClient;
    cout << "\nDelete Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pDeleteClient;
    cout << "\nUpdate Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pUpdateClients;
    cout << "\nFind Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pFindClient;
    cout << "\nTransactions? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pTransactions;
    cout << "\nManage Users? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pManageUsers;

    return Permissions;
}

void clsBankController::_ShowAddNewUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tAdd New User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "Enter UserName? "; cin >> UserName;
    while (clsUser::IsUserExist(UserName)) {
        cout << "\nUser with [" << UserName << "] already exists, Enter another UserName? ";
        cin >> UserName;
    }
    string Password;
    cout << "Enter Password? "; cin >> Password;
    int Permissions = ReadPermissions();

    clsUser::AddNewUser(clsUser("", "", UserName, Password, Permissions));
    cout << "\nUser Added Successfully.";
}

void clsBankController::_ShowDeleteUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tDelete User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "\nPlease enter UserName? "; cin >> UserName;
    if (UserName == "Admin") {
        cout << "\n\nYou cannot delete this user.";
        return;
    }

    clsUser User = clsUser::Find(UserName);
    if (User.GetUserName() != "") {
        char Answer;
        cout << "\nAre you sure you want to delete this user y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            clsUser::DeleteUser(UserName);
            cout << "\n\nUser Deleted Successfully.";
        }
    } else {
        cout << "\nUser with UserName (" << UserName << ") is Not Found!";
    }
}

void clsBankController::_ShowUpdateUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tUpdate User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "\nPlease enter UserName? "; cin >> UserName;

    clsUser User = clsUser::Find(UserName);
    if (User.GetUserName() != "") {
        char Answer;
        cout << "\nAre you sure you want to update this user y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            string Password;
            cout << "\n\nEnter Password? "; cin >> Password;
            int Permissions = ReadPermissions();

            User.SetPassword(Password);
            User.SetPermissions(Permissions);

            clsUser::UpdateUser(User);
            cout << "\n\nUser Updated Successfully.";
        }
    } else {
        cout << "\nUser with UserName (" << UserName << ") is Not Found!";
    }
}

void clsBankController::_ShowFindUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tFind User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "\nPlease enter UserName? "; cin >> UserName;

    clsUser User = clsUser::Find(UserName);
    if (User.GetUserName() != "") {
        cout << "\nThe following are the user details:\n";
        cout << "-----------------------------------";
        cout << "\nUsername   : " << User.GetUserName();
        cout << "\nPassword   : " << User.GetPassword();
        cout << "\nPermissions: " << User.GetPermissions();
        cout << "\n-----------------------------------\n";
    } else {
        cout << "\nUser with UserName (" << UserName << ") is Not Found!";
    }
}

