int clsBankController::_ReadPermissions() {
    int Permissions = 0;
    char Answer;
    cout << "\nDo you want to give full access? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') return -1;

    cout << "\nDo you want to give access to: \n ";
    cout << "\nShow Client List? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pListClients;
    cout << "\nAdd New Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pAddNewClient;
    cout << "\nDelete Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pDeleteClient;
    cout << "\nUpdate Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pUpdateClients;
    cout << "\nFind Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pFindClient;
    cout << "\nTransactions? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pTransactions;
    cout << "\nManage Users? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pManageUsers;

    return Permissions;
}

void clsBankController::_ShowAddNewUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tAdd New User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "Enter UserName? "; cin >> UserName;
    while (clsUser::IsUserExist(UserName)) {
        cout << "\nUser with [" << UserName << "] already exists, Enter another UserName? ";
        cin >> UserName;
    }
    string Password;
    cout << "Enter Password? "; cin >> Password;
    int Permissions = _ReadPermissions();

    clsUser::AddNewUser(clsUser("", "", UserName, Password, Permissions));
    cout << "\nUser Added Successfully.";
}

void clsBankController::_ShowDeleteUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tDelete User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "\nPlease enter UserName? "; cin >> UserName;
    if (UserName == "Admin") {
        cout << "\n\nYou cannot delete this user.";
        return;
    }

    clsUser User = clsUser::Find(UserName);
    if (!User.IsEmpty()) {
        char Answer;
        cout << "\nAre you sure you want to delete this user y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            clsUser::DeleteUser(UserName);
            cout << "\n\nUser Deleted Successfully.";
        }
    } else {
        cout << "\nUser with UserName (" << UserName << ") is Not Found!";
    }
}

void clsBankController::_ShowUpdateUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tUpdate User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "\nPlease enter UserName? "; cin >> UserName;

    clsUser User = clsUser::Find(UserName);
    if (!User.IsEmpty()) {
        char Answer;
        cout << "\nAre you sure you want to update this user y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            string Password;
            cout << "\n\nEnter Password? "; cin >> Password;
            int Permissions = _ReadPermissions();

            User.SetPassword(Password);
            User.SetPermissions(Permissions);

            clsUser::UpdateUser(User);
            cout << "\n\nUser Updated Successfully.";
        }
    } else {
        cout << "\nUser with UserName (" << UserName << ") is Not Found!";
    }
}

void clsBankController::_ShowFindUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tFind User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "\nPlease enter UserName? "; cin >> UserName;

    clsUser User = clsUser::Find(UserName);
