clsUser clsBankController::CurrentUser = clsUser("", "", "", "", 0);

void clsBankController::_ShowAccessDeniedMessage() {
    cout << "\n-----------------------------------\n";
    cout << "Access Denied, \nYou don't Have Permission To Do this,\nPlease Contact Your Admin.";
    cout << "\n-----------------------------------\n";
