```c/c++
#include "clsUser.h"
#include "Util.h"
#include <fstream>

clsUser::clsUser(std::string Name, std::string Phone, std::string UserName, std::string Password, int Permissions)
    : clsPerson(Name, Phone) {
    _UserName = UserName;
    _Password = Password;
    _Permissions = Permissions;
}

std::string clsUser::GetUserName() const {
    return _UserName;
}

void clsUser::SetPassword(std::string Password) {
    _Password = Password;
}

std::string clsUser::GetPassword() const {
    return _Password;
}

void clsUser::SetPermissions(int Permissions) {
    _Permissions = Permissions;
}

int clsUser::GetPermissions() const {
    return _Permissions;
}

bool clsUser::CheckAccessPermission(enPermissions Permission) const {
    if (this->GetPermissions() == enPermissions::eAll)
        return true;

    if ((Permission & this->GetPermissions()) == Permission)
        return true;
    else
        return false;
}

clsUser clsUser::_ConvertLineToRecord(std::string Line, std::string Separator) {
    std::vector<std::string> vUserData = Util::SplitString(Line, Separator);
    return clsUser("", "", vUserData[0], vUserData[1], std::stoi(vUserData[2]));
}

std::string clsUser::_ConvertRecordToLine(const clsUser& User, std::string Separator) {
    std::string stUserRecord = "";
    stUserRecord += User.GetUserName() + Separator;
    stUserRecord += User.GetPassword() + Separator;
    stUserRecord += std::to_string(User.GetPermissions());
    return stUserRecord;
}

std::vector<clsUser> clsUser::_LoadUsersDataFromFile() {
    std::vector<clsUser> vUsers;
    std::fstream MyFile;
    MyFile.open(USERS_FILE_PATH, std::ios::in);
    if (MyFile.is_open()) {
        std::string Line;
        while (std::getline(MyFile, Line)) {
            if (Line != "") {
                vUsers.push_back(_ConvertLineToRecord(Line));
            }
        }
        MyFile.close();
    }
    return vUsers;
}

void clsUser::_SaveUsersDataToFile(const std::vector<clsUser>& vUsers) {
    std::fstream MyFile;
    MyFile.open(USERS_FILE_PATH, std::ios::out);
    if (MyFile.is_open()) {
        for (const clsUser& U : vUsers) {
            if (!U.GetMarkForDelete()) {
                MyFile << _ConvertRecordToLine(U) << std::endl;
            }
        }
        MyFile.close();
    }
}

clsUser clsUser::Find(std::string UserName) {
    std::vector<clsUser> vUsers = _LoadUsersDataFromFile();
    for (const clsUser& U : vUsers) {
        if (U.GetUserName() == UserName) return U;
    }
    return clsUser("", "", "", "", 0);
}

clsUser clsUser::Find(std::string UserName, std::string Password) {
    std::vector<clsUser> vUsers = _LoadUsersDataFromFile();
    for (const clsUser& U : vUsers) {
        if (U.GetUserName() == UserName && U.GetPassword() == Password) return U;
    }
    return clsUser("", "", "", "", 0);
}

bool clsUser::IsUserExist(std::string UserName) {
    std::vector<clsUser> vUsers = _LoadUsersDataFromFile();
    for (const clsUser& U : vUsers) {
        if (U.GetUserName() == UserName) return true;
    }
    return false;
}

std::vector<clsUser> clsUser::GetUsersList() {
    return _LoadUsersDataFromFile();
}

void clsUser::AddNewUser(const clsUser& User) {
    std::fstream MyFile;
    MyFile.open(USERS_FILE_PATH, std::ios::out | std::ios::app);
    if (MyFile.is_open()) {
        MyFile << _ConvertRecordToLine(User) << std::endl;
        MyFile.close();
    }
}

void clsUser::UpdateUser(const clsUser& User) {
    std::vector<clsUser> vUsers = _LoadUsersDataFromFile();
    for (clsUser &U : vUsers) {
        if (U.GetUserName() == User.GetUserName()) {
            U = User;
            break;
        }
    }
    _SaveUsersDataToFile(vUsers);
}

void clsUser::DeleteUser(std::string UserName) {
    std::vector<clsUser> vUsers = _LoadUsersDataFromFile();
    for (clsUser &U : vUsers) {
        if (U.GetUserName() == UserName) {
            U.MarkForDeleted();
            break;
        }
    }
    _SaveUsersDataToFile(vUsers);
}

bool clsUser::IsEmpty() const {
    return _UserName == "";
}

