int clsBankController::_ReadPermissions() {
    int Permissions = 0;
    char Answer;
    cout << "\nDo you want to give full access? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') return -1;

    cout << "\nDo you want to give access to: \n ";
    cout << "\nShow Client List? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pListClients;
    cout << "\nAdd New Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pAddNewClient;
    cout << "\nDelete Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pDeleteClient;
    cout << "\nUpdate Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pUpdateClients;
    cout << "\nFind Client? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pFindClient;
    cout << "\nTransactions? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pTransactions;
    cout << "\nManage Users? y/n? "; cin >> Answer;
    if (Answer == 'y' || Answer == 'Y') Permissions += clsUser::enPermissions::pManageUsers;

    return Permissions;
}

