    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "\nPlease enter UserName? "; cin >> UserName;

    clsUser User = clsUser::Find(UserName);
    if (!User.IsEmpty()) {
        char Answer;
        cout << "\nAre you sure you want to update this user y/n? "; cin >> Answer;
        if (Answer == 'y' || Answer == 'Y') {
            string Password;
            cout << "\n\nEnter Password? "; cin >> Password;
            int Permissions = _ReadPermissions();

            User.SetPassword(Password);
            User.SetPermissions(Permissions);

            clsUser::UpdateUser(User);
            cout << "\n\nUser Updated Successfully.";
        }
    } else {
        cout << "\nUser with UserName (" << UserName << ") is Not Found!";
    }
}

void clsBankController::_ShowFindUserScreen() {
    cout << "\n-----------------------------------\n";
    cout << "\tFind User Screen";
    cout << "\n-----------------------------------\n";
    string UserName;
    cout << "\nPlease enter UserName? "; cin >> UserName;

